package com.example.homestay;
import android.content.Intent;import android.net.Uri;import android.os.Bundle;import android.text.*;import android.view.View;import android.widget.*;import androidx.activity.result.ActivityResultLauncher;import androidx.activity.result.contract.ActivityResultContracts;import androidx.appcompat.app.*;import androidx.appcompat.widget.Toolbar;import androidx.recyclerview.widget.*;import com.example.homestay.data.entity.*;import com.example.homestay.data.model.AdminRoomData;import com.example.homestay.data.repository.HomestayRepository;import com.example.homestay.ui.admin.AdminRoomAdapter;import com.example.homestay.utils.*;import com.google.android.material.chip.ChipGroup;import com.google.android.material.dialog.MaterialAlertDialogBuilder;import com.google.android.material.floatingactionbutton.FloatingActionButton;import com.google.android.material.materialswitch.MaterialSwitch;import com.google.android.material.textfield.TextInputEditText;import java.text.*;import java.util.*;import java.util.concurrent.Executors;
public class AdminRoomsActivity extends AppCompatActivity{
 private HomestayRepository repository;private AdminRoomAdapter adapter;private ProgressBar progress;private final List<AdminRoomData> rooms=new ArrayList<>();private List<Booking> bookings=Collections.emptyList();private Boolean availableFilter;private TextInputEditText imageField;private ImageView imagePreview;private ActivityResultLauncher<String[]> imagePicker;
 @Override protected void onCreate(Bundle s){super.onCreate(s);imagePicker=registerForActivityResult(new ActivityResultContracts.OpenDocument(),uri->{if(uri==null)return;try{getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}if(imageField!=null)imageField.setText(uri.toString());if(imagePreview!=null)loadImage(imagePreview,uri.toString());});setContentView(R.layout.activity_admin_rooms);SystemBarUtils.keepContentBelowStatusBar(this);repository=((HomestayApplication)getApplication()).getRepository();Toolbar t=findViewById(R.id.toolbar);setSupportActionBar(t);if(getSupportActionBar()!=null){getSupportActionBar().setDisplayHomeAsUpEnabled(false);getSupportActionBar().setTitle("Quản lý Phòng");}setup();AdminNavigationUtils.setup(this,R.id.admin_nav_rooms);load();}
 private void setup(){progress=findViewById(R.id.progress_bar);adapter=new AdminRoomAdapter(new ArrayList<>(),this::showEdit,this::confirmDelete,this::details);RecyclerView list=findViewById(R.id.rv_rooms);list.setLayoutManager(new LinearLayoutManager(this));list.setAdapter(adapter);TextInputEditText search=findViewById(R.id.et_admin_search);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int c){}public void onTextChanged(CharSequence s,int a,int b,int c){filter(s.toString());}public void afterTextChanged(Editable e){}});ChipGroup chips=findViewById(R.id.chip_room_status);chips.clearCheck();chips.check(R.id.chip_rooms_all);chips.setOnCheckedStateChangeListener((g,ids)->{int id=ids.isEmpty()?View.NO_ID:ids.get(0);availableFilter=id==R.id.chip_rooms_active?Boolean.TRUE:id==R.id.chip_rooms_hidden?Boolean.FALSE:null;filter(text(search));});((FloatingActionButton)findViewById(R.id.fab_add_room)).setOnClickListener(v->showDialog(null));}
 private void load(){progress.setVisibility(View.VISIBLE);Executors.newSingleThreadExecutor().execute(()->{bookings=repository.getAllBookingsNow();List<AdminRoomData> result=new ArrayList<>();for(Room room:repository.getAllRoomsNow())result.add(toAdmin(room));runOnUiThread(()->{rooms.clear();rooms.addAll(result);filter(text((TextInputEditText)findViewById(R.id.et_admin_search)));progress.setVisibility(View.GONE);});});}
 private AdminRoomData toAdmin(Room r){int count=0;double revenue=0;for(Booking b:bookings)if(b.getRoomId()==r.getId()){count++;if("completed".equals(b.getStatus()))revenue+=b.getTotalPrice();}return new AdminRoomData(String.valueOf(r.getId()),r.getName(),r.getDescription(),r.getPrice(),r.getMaxGuests(),r.getImageUrl(),r.getMaxSlots(),0,r.getLocation(),r.getAddress(),r.getAmenities(),r.getRoomType(),r.getArea(),r.getRating(),r.getReviewCount(),r.isAvailable(),r.isFeatured(),count,revenue);}
 private void filter(String q){if(adapter==null)return;String key=q.trim().toLowerCase(Locale.ROOT);List<AdminRoomData> out=new ArrayList<>();for(AdminRoomData r:rooms)if((availableFilter==null||r.isAvailable()==availableFilter)&&((r.getName()+" "+r.getLocation()+" "+r.getRoomType()+" "+r.getAmenities()).toLowerCase(Locale.ROOT).contains(key)))out.add(r);adapter.updateRooms(out);findViewById(R.id.tv_empty).setVisibility(out.isEmpty()?View.VISIBLE:View.GONE);}
 private void showEdit(AdminRoomData room){showDialog(room);}private void showDialog(AdminRoomData room){View view=getLayoutInflater().inflate(R.layout.dialog_add_edit_room,null);Fields f=new Fields(view);((TextView)view.findViewById(R.id.tv_dialog_title)).setText(room==null?"Thêm phòng mới":"Chỉnh sửa phòng");if(room!=null){f.name.setText(room.getName());f.description.setText(room.getDescription());f.price.setText(String.valueOf(room.getPrice()));f.capacity.setText(String.valueOf(room.getCapacity()));f.slots.setText(String.valueOf(room.getMaxSlots()));f.image.setText(room.getImageUrl());loadImage(f.preview,room.getImageUrl());f.type.setText(room.getRoomType());f.location.setText(room.getLocation());f.address.setText(room.getAddress());f.area.setText(String.valueOf(room.getArea()));f.amenities.setText(room.getAmenities());f.available.setChecked(room.isAvailable());f.featured.setChecked(room.isFeatured());}view.findViewById(R.id.btn_select_room_image).setOnClickListener(v->{imageField=f.image;imagePreview=f.preview;imagePicker.launch(new String[]{"image/*"});});AlertDialog dialog=new MaterialAlertDialogBuilder(this).setView(view).setCancelable(true).create();view.findViewById(R.id.btn_cancel).setOnClickListener(v->dialog.dismiss());view.findViewById(R.id.btn_save).setOnClickListener(v->save(room,f,dialog));dialog.show();}
 private void save(AdminRoomData existing,Fields f,AlertDialog dialog){String name=text(f.name).trim(),description=text(f.description).trim(),image=text(f.image).trim();Double price=number(text(f.price));Integer capacity=integer(text(f.capacity)),slots=integer(text(f.slots));if(!validImage(image)){f.image.setError("Ảnh không hợp lệ, vui lòng chọn lại từ thiết bị");return;}if(name.isEmpty()||price==null||capacity==null){toast("Vui lòng điền đầy đủ thông tin");return;}if(price<=0||capacity<1||capacity>20||slots==null||slots<1||slots>20){toast("Giá phải lớn hơn 0; sức chứa và số phòng từ 1 đến 20");return;}int area=integer(text(f.area))==null?0:integer(text(f.area));Executors.newSingleThreadExecutor().execute(()->{try{if(f.featured.isChecked())repository.clearFeaturedRooms();if(existing==null)repository.insertRoom(new Room(0,null,name,description,price,image,text(f.location),text(f.address),5f,0,blank(text(f.amenities),"WiFi"),capacity,blank(text(f.type),"Homestay"),area,slots,f.available.isChecked(),f.featured.isChecked()));else{Room current=repository.getRoomById(Long.parseLong(existing.getId()));if(current!=null)repository.updateRoom(current.updated(name,description,price,image,text(f.location),text(f.address),text(f.amenities),capacity,blank(text(f.type),"Homestay"),area,slots,f.available.isChecked(),f.featured.isChecked()));}runOnUiThread(()->{dialog.dismiss();toast(existing==null?"Thêm phòng thành công!":"Cập nhật phòng thành công!");load();});}catch(Exception e){runOnUiThread(()->toast("Lỗi: "+e.getMessage()));}});}
 private void confirmDelete(AdminRoomData room){new MaterialAlertDialogBuilder(this).setTitle("Xóa phòng").setMessage("Bạn có chắc muốn xóa phòng \""+room.getName()+"\"?").setPositiveButton("Xóa",(d,w)->Executors.newSingleThreadExecutor().execute(()->{Room value=repository.getRoomById(Long.parseLong(room.getId()));if(value!=null&&repository.roomHasBookings(value.getId())){runOnUiThread(()->toast("Không thể xóa phòng đang có booking"));return;}if(value!=null)repository.deleteRoom(value);runOnUiThread(()->{toast("Xóa phòng thành công!");load();});})).setNegativeButton("Hủy",null).show();}
 private void details(AdminRoomData r){String price=money(r.getPrice()),revenue=money(r.getRevenue());new MaterialAlertDialogBuilder(this).setTitle(r.getName()).setMessage("Mã phòng: "+r.getId()+"\nLoại: "+r.getRoomType()+"\nTrạng thái: "+(r.isAvailable()?"Đang mở":"Tạm ẩn")+"\nGiá: "+price+" đ/đêm\nĐịa điểm: "+r.getLocation()+"\nĐịa chỉ: "+r.getAddress()+"\nDiện tích: "+r.getArea()+" m²\nSức chứa: "+r.getCapacity()+" người\nSố slot: "+r.getMaxSlots()+"\nĐánh giá: "+r.getRating()+" sao · "+(r.getReviewCount()==0?"Chưa có đánh giá":r.getReviewCount()+" lượt")+"\nTiện nghi: "+r.getAmenities()+"\n\nBooking: "+r.getBookingCount()+"\nDoanh thu thực tế: "+revenue+" đ\n\nMô tả:\n"+r.getDescription()).setNegativeButton("Đóng",null).setPositiveButton("Chỉnh sửa",(d,w)->showEdit(r)).show();}
 private boolean validImage(String value){if(value.trim().isEmpty())return true;try{Uri u=Uri.parse(value);if("content".equals(u.getScheme()))return true;if(!"https".equals(u.getScheme())||u.getHost()==null)return false;String p=u.getPath()==null?"":u.getPath().toLowerCase(Locale.ROOT);return!p.endsWith(".html")&&!p.endsWith(".htm");}catch(Exception e){return false;}}private void loadImage(ImageView v,String data){ImageLoader.load(v,data,R.drawable.ic_room_placeholder);}
 private static String text(TextInputEditText f){return f.getText()==null?"":f.getText().toString();}private static String blank(String s,String fallback){return s.trim().isEmpty()?fallback:s;}private static Double number(String s){try{return Double.valueOf(s);}catch(Exception e){return null;}}private static Integer integer(String s){try{return Integer.valueOf(s);}catch(Exception e){return null;}}private static String money(double n){return NumberFormat.getNumberInstance(new Locale("vi","VN")).format((long)n);}private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}
 private static final class Fields{final TextInputEditText name,description,price,capacity,slots,image,type,location,address,area,amenities;final ImageView preview;final MaterialSwitch available,featured;Fields(View v){name=v.findViewById(R.id.et_room_name);description=v.findViewById(R.id.et_room_description);price=v.findViewById(R.id.et_room_price);capacity=v.findViewById(R.id.et_room_capacity);slots=v.findViewById(R.id.et_room_max_slots);image=v.findViewById(R.id.et_room_image_url);preview=v.findViewById(R.id.iv_room_image_preview);type=v.findViewById(R.id.et_room_type);location=v.findViewById(R.id.et_room_location);address=v.findViewById(R.id.et_room_address);area=v.findViewById(R.id.et_room_area);amenities=v.findViewById(R.id.et_room_amenities);available=v.findViewById(R.id.switch_room_available);featured=v.findViewById(R.id.switch_room_featured);}}
}
